// src/index.js — after fix
app.post('/pay', async (req, res) => {
  const decoded = verifyToken(req.headers.authorization);
  if (!decoded) return res.status(401).json({ error: 'Unauthorized' });
  const result = await processPayment(req.body.amount);
  res.json(result);
});
// src/payment.js — fetch the rate inside processPayment
const exchangeRateService = require('./services/exchangeRateService');
async function processPayment(amount) {
  const rate = await exchangeRateService.getUsdRate();
  return { original: amount, converted: amount * rate, status: 'processed' };
}

